const WEAPON_MUTATIONS={};
function vsxEnsureWeaponMutations(id){
 const d=WEAPON_DEFINITIONS[id];
 if(!d||(d.rewardOnly&&!d.marvelSignatureMutation))return [];
 if(Array.isArray(WEAPON_MUTATIONS[id])&&WEAPON_MUTATIONS[id].length)return WEAPON_MUTATIONS[id];
 const football=d.tags?.includes("football")||["football","bicycle_kick","corner_kick","golden_boots","crown_no10","wizard_elastico","samba_streetball"].includes(id);
 WEAPON_MUTATIONS[id]=[
  {id:id+"__tempo",name:{en:football?"Hat Trick":"Tempo Form",vi:football?"Hat-trick":"Biến Thể Tốc Chiến"},desc:{en:"Faster cadence and broader coverage.",vi:football?"Tăng nhịp triển khai và độ phủ như một pha phối hợp tốc độ.":"Ra đòn dồn dập hơn và phủ mục tiêu rộng hơn."},mods:{cooldownMul:.80,speedMul:1.12,countAdd:1,pierceAdd:1,damageMul:.94}},
  {id:id+"__power",name:{en:football?"Cannon Ball":"Power Form",vi:football?"Cú Đại Bác":"Biến Thể Trọng Kích"},desc:{en:"Slower, heavier hits with much higher impact.",vi:football?"Ít bóng hơn nhưng mỗi cú sút như đại bác, sát thương và lực hất văng tăng mạnh.":"Ra đòn chậm hơn nhưng mỗi hit nặng hơn rất nhiều."},mods:{damageMul:1.55,sizeMul:1.25,knockbackMul:1.3,cooldownMul:1.18}}
 ];
 return WEAPON_MUTATIONS[id];
}
for(const [id] of Object.entries(WEAPON_DEFINITIONS))vsxEnsureWeaponMutations(id);

