Object.defineProperty(WeaponInstance.prototype,"name",{configurable:true,get(){return this.evolutionId?evolutionName(this.evolutionId):weaponName(this.id)}});
const VSX_BASE_ADD_WEAPON=Player.prototype.addWeapon;
Player.prototype.addWeapon=function(id){const ok=VSX_BASE_ADD_WEAPON.call(this,id);if(ok)vsxDiscover("weapons",id);return ok};
const VSX_BASE_ADD_PASSIVE=Player.prototype.addPassive;
Player.prototype.addPassive=function(id){const ok=VSX_BASE_ADD_PASSIVE.call(this,id);if(ok)vsxDiscover("passives",id);return ok};

const VSX_BASE_STATS=WeaponInstance.prototype.getStats;
WeaponInstance.prototype.getStats=function(){let s=VSX_BASE_STATS.call(this);if(this.mutationId){const m=(WEAPON_MUTATIONS[this.id]||[]).find(x=>x.id===this.mutationId)?.mods;if(m){for(const [k,v] of Object.entries(m)){if(k.endsWith("Mul")){const q=k.slice(0,-3);s[q]=(s[q]??1)*v}else if(k.endsWith("Add")){const q=k.slice(0,-3);s[q]=(s[q]??0)+v}}}}if(game?.activeSynergies?.has("anfield_fortress")&&this.id==="virgil_vandijk"){s.wallHp*=1.45;s.wallWidth*=1.18;s.duration*=1.18}if(game?.characterId==="technician"&&this.def.tags?.some(x=>["deployable","defensive"].includes(x))){s.duration*=1.25;s.wallHp*=1.25;s.area*=1.12}return s};

const VSX_BASE_RECALC=Player.prototype.recalc;
Player.prototype.recalc=function(){const prevHp=this.hp;VSX_BASE_RECALC.call(this);const c=CHARACTER_DEFINITIONS[game?.characterId]?.mods||{};this.maxHp=Math.max(1,Math.round(this.maxHp*(c.hp||1)));if((c.hp||1)>1&&prevHp>this.hp)this.hp=Math.min(this.maxHp,prevHp);if(this.hp>this.maxHp)this.hp=this.maxHp;this.damageMultiplier*=c.damage||1;this.moveSpeed*=c.move||1;this.armor+=c.armor||0;this.dodge=Math.min(.45,this.dodge+(c.dodge||0));this.luck+=c.luck||0;this.incomingMultiplier*=c.incoming||1;if(game?.activeSynergies?.has("full_sprint")&&this.movingTime>0)this.moveSpeed*=1.10;if(game?.activeSynergies?.has("one_man_army"))this.damageMultiplier*=1.15;if(game?.ultimateBuff?.id==="unbreakable")this.damageReduction=Math.min(.8,this.damageReduction+.50);if(game?.ultimateBuff?.id==="breakaway"){this.moveSpeed*=1.85;this.dodge=Math.min(.45,this.dodge+.25)}this.damageReduction=Math.min(.75,this.damageReduction);this.dodge=Math.min(.45,this.dodge)};

const VSX_BASE_ALLY_DMG=Game.prototype.allyDamageMultiplier;
Game.prototype.allyDamageMultiplier=function(){let m=VSX_BASE_ALLY_DMG.call(this);const c=CHARACTER_DEFINITIONS[this.characterId]?.mods;if(c?.allyDamage)m*=c.allyDamage;if(this.activeSynergies?.has("counter_attack"))m*=1.22;return Math.min(2.5,m)};
const VSX_BASE_ALLY_ATK=Game.prototype.allyAttackSpeedMultiplier;
Game.prototype.allyAttackSpeedMultiplier=function(){let m=VSX_BASE_ALLY_ATK.call(this);const c=CHARACTER_DEFINITIONS[this.characterId]?.mods;if(c?.allySpeed)m*=c.allySpeed;return Math.min(2.2,m)};

