VSX.renderSetup=function(){const grid=document.getElementById("vsxCharacterGrid");if(!grid)return;document.getElementById("vsxSetupTitle").textContent=t("chooseFighter");document.getElementById("vsxDiffTitle").textContent=t("chooseDifficulty");document.getElementById("vsxBeginBtn").textContent=t("begin");document.getElementById("vsxSetupBack").textContent=t("back");grid.innerHTML="";for(const [id,d] of Object.entries(CHARACTER_DEFINITIONS)){const el=document.createElement("div");el.className="vsxPick"+(VSX.selectedCharacter===id?" selected":"");el.innerHTML=`<h3>${VSX.esc(d.name[VSX.lang])}</h3><p>${VSX.esc(d.desc[VSX.lang])}</p><p style="margin-top:7px;color:#8fd0ff"><b>${VSX.lang==="vi"?"Vũ khí":"Weapon"}:</b> ${VSX.esc(weaponName(d.weapon))}</p>`;el.onclick=()=>{VSX.selectedCharacter=id;VSX.renderSetup()};grid.appendChild(el)}const dg=document.getElementById("vsxDifficulty");dg.innerHTML="";for(const [id,d] of Object.entries(DIFFICULTY_DEFINITIONS)){const b=document.createElement("button");b.className=VSX.selectedDifficulty===id?"selected":"";b.textContent=d.name[VSX.lang];b.onclick=()=>{VSX.selectedDifficulty=id;VSX.renderSetup()};dg.appendChild(b)}};
VSX.showSetup=function(){titleScreen.classList.remove("active");gameOverScreen.classList.remove("active");pauseScreen.classList.remove("active");hud.classList.remove("active");document.getElementById("vsxSetupScreen").classList.add("active");VSX.renderSetup()};

VSX.codexEntries=function(cat){if(cat==="weapons")return Object.keys(WEAPON_DEFINITIONS).map(id=>[id,weaponName(id),weaponDesc(id)]);if(cat==="passives")return Object.keys(PASSIVE_DEFINITIONS).map(id=>[id,passiveName(id),passiveDesc(id)]);if(cat==="evolutions")return Object.keys(EVOLUTION_DEFINITIONS).map(id=>[id,evolutionName(id),VSX.lang==="vi"?"Tiến hóa vũ khí đặc biệt.":"Special weapon evolution."]);if(cat==="mutations")return Object.entries(WEAPON_MUTATIONS).flatMap(([id,a])=>a.map(m=>[m.id,m.name[VSX.lang],m.desc[VSX.lang]]));if(cat==="synergies")return Object.entries(SYNERGY_DEFINITIONS).map(([id,d])=>[id,d.name[VSX.lang],VSX.lang==="vi"?"Cộng hưởng build đã được phát hiện.":"Discovered build synergy."]);if(cat==="enemies")return Object.entries(ENEMY_DEFINITIONS).map(([id,d])=>[id,d.name,VSX.lang==="vi"?"Kẻ địch đã chạm trán.":"Encountered enemy."]).concat(Object.entries(MINIBOSS_DEFINITIONS).map(([id,d])=>["mini_"+id,d.name[VSX.lang],t("miniboss")]));if(cat==="bosses")return [["crimson_titan",VSX.lang==="vi"?"Titan Đỏ Thẫm":"Crimson Titan",VSX.lang==="vi"?"Boss chính nhiều giai đoạn.":"Multi-phase major boss."]];if(cat==="characters")return Object.entries(CHARACTER_DEFINITIONS).map(([id,d])=>[id,d.name[VSX.lang],d.desc[VSX.lang]]);if(cat==="achievements")return Object.entries(ACHIEVEMENT_DEFINITIONS).map(([id,d])=>[id,d.name[VSX.lang],d.desc[VSX.lang]]);return[]};
VSX.showCollection=function(){titleScreen.classList.remove("active");const sc=document.getElementById("vsxCollectionScreen");sc.classList.add("active");document.getElementById("vsxCollectionTitle").textContent=t("collection");document.getElementById("vsxCollectionBack").textContent=t("back");const tabs=document.getElementById("vsxCodexTabs"),cats=["weapons","passives","evolutions","mutations","synergies","enemies","bosses","characters","achievements"];tabs.innerHTML="";for(const c of cats){const b=document.createElement("button");const n=VSX.codexEntries(c).length,got=Object.keys(VSX.save.codex[c]||{}).length;b.textContent=`${c.toUpperCase()} ${got}/${n}`;b.onclick=()=>VSX.renderCodex(c);tabs.appendChild(b)}VSX.renderCodex("weapons")};
VSX.renderCodex=function(cat){const list=document.getElementById("vsxCodexList");list.innerHTML="";const seen=VSX.save.codex[cat]||{};for(const [id,n,d] of VSX.codexEntries(cat)){const unlocked=!!seen[id]||cat==="characters";const e=document.createElement("div");e.className="vsxCodexItem";e.innerHTML=unlocked?`<b>${VSX.esc(n)}</b>${VSX.esc(d)}`:`<b>???</b>${VSX.lang==="vi"?"Chưa khám phá":"Undiscovered"}`;list.appendChild(e)}};

// ---------- Core start/save/difficulty ----------
const VSX_BASE_START=Game.prototype.start;
Game.prototype.start=function(){VSX.showSetup()};
VSX.beginRun=function(){document.getElementById("vsxSetupScreen").classList.remove("active");VSX_BASE_START.call(game);game.player.weaponSlots=MAX_WEAPON_SLOTS;game.player.passiveSlots=MAX_PASSIVE_SLOTS;game.characterId=VSX.selectedCharacter;game.difficultyMode=VSX.selectedDifficulty;game.records=VSX.save.records[game.difficultyMode];game.vsxInitRun();const c=CHARACTER_DEFINITIONS[game.characterId];if(c.weapon!=="pulse_blaster"){game.player.weapons=[];game.player.addWeapon(c.weapon)}vsxDiscover("characters",game.characterId);game.player.recalc();game.player.hp=game.player.maxHp;game.renderRecords();game.updateHUD(true)};
Game.prototype.vsxInitRun=function(){this.activeSynergies=new Set();this.rewardQueue=[];this.metaBusy=false;this.dashCooldown=0;this.dashTimer=0;this.dashDir={x:1,y:0};this.lastMoveDir={x:1,y:0};this.ultimateCharge=0;this.ultimateActive=false;this.ultimateBuff=null;this.ultKillHeat=0;this.worldEvent=null;this.eventCooldown=55;this.eventTick=0;this.miniBoss=null;this.miniBossCooldown=80;this.formationCooldown=28;this.worldObjectCooldown=12;this.worldObjects=[];this.telegraphs=[];this.healingZones=[];this.lastMajorEncounterTime=-99;this.recentDeaths=[];this.shrineMods={damage:1,xp:1,enemyHp:1,elite:1};this.killStreak={count:0,timer:0,footballKills:0,footballTimer:0};this.stats={damageBy:{},damageDealt:0,damageTaken:0,damagePrevented:0,healing:0,overshield:0,xp:0,medkits:0,rerolls:0,skips:0,highestHit:0,crits:0,dashes:0,ultimates:0,elites:0,minibosses:0,bosses:0,shrines:0,vvdBlocked:0,projectilesCaught:0,projectilesBlocked:0,synergies:new Set(),hpDamageTaken:0};this.hudClock=0;this.debugMeta=false;this.mutationQueued=new Set();this.encounterSerial=0;this.eventSpawnTimer=0;this.ultimateBuffTimer=0};
Game.prototype.saveRecords=function(){const r=VSX.save.records[this.difficultyMode||"normal"]||(VSX.save.records[this.difficultyMode||"normal"]=vsxDefaultRecord());r.score=Math.max(r.score,Math.floor(this.score));r.time=Math.max(r.time,this.time||0);r.kills=Math.max(r.kills,this.kills||0);r.level=Math.max(r.level,this.player?.level||0);r.bosses=Math.max(r.bosses,this.bossesDefeated||0);this.records=r;vsxSave();this.renderRecords()};
Game.prototype.renderRecords=function(){const r=VSX.save.records?.[this.difficultyMode||VSX.selectedDifficulty||"normal"]||vsxDefaultRecord();const el=document.getElementById("records");if(el)el.innerHTML=`<div><small>${t("bestScore")}</small><strong>${r.score}</strong></div><div><small>${t("longest")}</small><strong>${fmtTime(r.time)}</strong></div><div><small>${t("mostKills")}</small><strong>${r.kills}</strong></div><div><small>${t("highestLevel")}</small><strong>${r.level}</strong></div><div><small>${t("mostBosses")}</small><strong>${r.bosses}</strong></div>`};

function vsxApplyDifficulty(e){if(!e||e._vsxDifficulty)return e;e._vsxDifficulty=true;const d=DIFFICULTY_DEFINITIONS[game.difficultyMode||"normal"];e.maxHp*=d.hp*(game.shrineMods?.enemyHp||1);e.hp=e.maxHp;e.damage*=d.damage;e.speed*=d.speed;return e}
const VSX_BASE_SPAWN_ONE=SpawnManager.prototype.spawnOne;
SpawnManager.prototype.spawnOne=function(forceElite=false){const mode=DIFFICULTY_DEFINITIONS[game.difficultyMode||"normal"],event=game.worldEvent?.id;if(event==="elite_invasion"&&Math.random()<.6)forceElite=true;else if(mode.elite>1&&Math.random()<GAME_CONFIG.eliteBaseChance*(mode.elite-1))forceElite=true;const n=game.enemies.length;VSX_BASE_SPAWN_ONE.call(this,forceElite);for(let i=n;i<game.enemies.length;i++){const e=vsxApplyDifficulty(game.enemies[i]);if(event==="golden_rush"&&Math.random()<.32){e.golden=true;e.xp=Math.round(e.xp*2.2)}}};
const VSX_BASE_SPECIAL=SpawnManager.prototype.trySpecialSpawns;
SpawnManager.prototype.trySpecialSpawns=function(){if(game.worldEvent||game.boss||game.miniBoss||game.time-game.lastMajorEncounterTime<15)return;const before={...game.specialSpawned};VSX_BASE_SPECIAL.call(this);for(const k of Object.keys(game.specialSpawned||{}))if(!before[k]&&game.specialSpawned[k])game.lastMajorEncounterTime=game.time};
const VSX_BASE_SPAWN_BOSS=SpawnManager.prototype.spawnBoss;
SpawnManager.prototype.spawnBoss=function(){if(game.worldEvent||game.miniBoss||game.time-game.lastMajorEncounterTime<15)return;VSX_BASE_SPAWN_BOSS.call(this);if(game.boss){vsxApplyDifficulty(game.boss);game.boss.vsxPhase=1;game.boss.vsxAbilityTimer=5;game.lastMajorEncounterTime=game.time;vsxDiscover("bosses","crimson_titan")}};

// ---------- Damage attribution / statistics ----------
function vsxSourceId(o){if(game._damageAttribution)return game._damageAttribution;if(o?.source?.id)return o.source.id;if(o?.damageType)return o.damageType;return "environment"}
const VSX_BASE_DAMAGE=Game.prototype.damageEnemy;
Game.prototype.damageEnemy=function(e,amount,o={}){const before=e?.hp||0;const result=VSX_BASE_DAMAGE.call(this,e,amount,o);const dealt=Math.max(0,Math.min(before,before-(e?.hp||0)));if(dealt>0&&this.stats){const id=vsxSourceId(o);this.stats.damageDealt+=dealt;this.stats.damageBy[id]=(this.stats.damageBy[id]||0)+dealt;this.stats.highestHit=Math.max(this.stats.highestHit,dealt);if(result?.crit)this.stats.crits++;if(o.source?.id==="golden_ball_cannon")this.texts.push(new FloatingText(e.x,e.y-e.size-20,`GB ${Math.round(dealt)}`,"#ffd84d",14));if(result?.killed&&(e.statuses?.has("burn")||e.statuses?.has("poison")))this.texts.push(new FloatingText(e.x,e.y-e.size-30,e.statuses.has("burn")?"BURN":"POISON",e.statuses.has("burn")?"#ff7a35":"#65df78",12))}return result};
const VSX_BASE_TAKE=Player.prototype.takeDamage;
Player.prototype.takeDamage=function(amount,src={}){const hp=this.hp,sh=(this.barrierHp||0)+(this.overhealShield||0)+(this.guardianShield?amount:0)+(this.pickupShield?amount:0)+(this.networkShieldTimer>0?amount:0);VSX_BASE_TAKE.call(this,amount,src);if(game.stats){const loss=Math.max(0,hp-this.hp);game.stats.damageTaken+=loss;game.stats.hpDamageTaken+=loss;game.stats.damagePrevented+=Math.max(0,amount-loss);if(loss>0)game.stats.cleanSheetBroken=true}return};
const VSX_BASE_HEAL=Player.prototype.heal;
Player.prototype.heal=function(...a){const hp=this.hp,os=this.overhealShield||0;const r=VSX_BASE_HEAL.apply(this,a);if(game.stats){game.stats.healing+=Math.max(0,this.hp-hp);game.stats.overshield+=Math.max(0,(this.overhealShield||0)-os)}return r};
const VSX_BASE_XP=Player.prototype.gainXP;
Player.prototype.gainXP=function(v,...rest){let mult=game.worldEvent?.id==="blood_moon"?1.65:game.worldEvent?.id==="overtime"?1.35:1;mult*=game.shrineMods?.xp||1;const before=game.score;const out=VSX_BASE_XP.call(this,v*mult,...rest);if(game.stats)game.stats.xp+=v*mult;const sm=DIFFICULTY_DEFINITIONS[game.difficultyMode||"normal"].score;if(sm!==1)game.score=before+(game.score-before)*sm;return out};
const VSX_BASE_PICKUP=Game.prototype.collectPickup;
Game.prototype.collectPickup=function(p){if(this.stats&&p.type==="medkit")this.stats.medkits++;return VSX_BASE_PICKUP.call(this,p)};

// mark clone/MB9 attribution
const VSX_BASE_MBAPPE_UPDATE=MbappeAlly.prototype.update;
MbappeAlly.prototype.update=function(dt){game._damageAttribution="MB9";try{return VSX_BASE_MBAPPE_UPDATE.call(this,dt)}finally{game._damageAttribution=null}};
const VSX_BASE_CLONE_UPDATE=SpiritClone.prototype.update;
SpiritClone.prototype.update=function(dt,p){const n=game.projectiles.length;VSX_BASE_CLONE_UPDATE.call(this,dt,p);for(let i=n;i<game.projectiles.length;i++)if(!game.projectiles[i].weapon)game.projectiles[i].statSourceId="clones"};
const VSX_BASE_PROJ_HIT=Projectile.prototype.hitEnemies;
Projectile.prototype.hitEnemies=function(){const old=game._damageAttribution;if(this.statSourceId)game._damageAttribution=this.statSourceId;try{return VSX_BASE_PROJ_HIT.call(this)}finally{game._damageAttribution=old}};

// ---------- Crowd control resolver ----------
const VSX_BASE_STATUS=Enemy.prototype.applyStatus;
Enemy.prototype.applyStatus=function(type,duration,strength,source){if(this.isBoss){this._ccHeat=Math.max(0,(this._ccHeat||0)-.08);const resist=clamp(1-(this._ccHeat||0)*.12,.25,1);duration*=.28*resist;this._ccHeat=(this._ccHeat||0)+1;if(type==="freeze"){type="slow";strength=Math.min(.35,.22+strength*.12);duration=Math.max(.4,duration)}if(type==="slow")strength=Math.min(.35,strength)}else if(this.isMiniBoss){duration*=.45;if(type==="freeze")duration=Math.min(.45,duration);if(type==="slow")strength=Math.min(.55,strength)}else if(this.elite)duration*=.65;return VSX_BASE_STATUS.call(this,type,duration,strength,source)};

// ---------- Dash / Ultimate ----------
Game.prototype.tryDash=function(){if(this.state!=="PLAYING"||this.dashCooldown>0||this.dashTimer>0)return;let dx=0,dy=0;if(this.input.has("KeyW")||this.input.has("ArrowUp"))dy--;if(this.input.has("KeyS")||this.input.has("ArrowDown"))dy++;if(this.input.has("KeyA")||this.input.has("ArrowLeft"))dx--;if(this.input.has("KeyD")||this.input.has("ArrowRight"))dx++;if(dx||dy)this.lastMoveDir=normalize(dx,dy);this.dashDir={...(this.lastMoveDir||{x:1,y:0})};this.dashTimer=.20;this.dashCooldown=4.5;this.stats.dashes++;this.player.invuln=Math.max(this.player.invuln,.16);this.audio.beep(530,.05,"sine",.018)};
Game.prototype.addUltimateCharge=function(v){if(this.ultimateActive)return;this.ultimateCharge=clamp(this.ultimateCharge+v,0,100);if(this.ultimateCharge>=100&&!this._ultReadyAnnounced){this._ultReadyAnnounced=true;VSX.announce(t("ultimate"),t("ready"),"#b38cff");this.audio.beep(980,.13,"triangle",.03)}};
Game.prototype.useUltimate=function(){if(this.state!=="PLAYING"||this.ultimateCharge<100||this.ultimateActive)return;this.ultimateCharge=0;this._ultReadyAnnounced=false;this.ultimateActive=true;this.stats.ultimates++;const id=CHARACTER_DEFINITIONS[this.characterId].ultimate;VSX.announce(t("ultimate"),CHARACTER_DEFINITIONS[this.characterId].name[VSX.lang],"#b879ff");if(id==="power_shot"){const target=this.findNearest(this.player.x,this.player.y,900),a=target?Math.atan2(target.y-this.player.y,target.x-this.player.x):Math.atan2(this.lastMoveDir.y,this.lastMoveDir.x),w={id:"ultimate_power_shot",def:{tags:["ultimate","projectile"]}};this.projectiles.push(new Projectile({x:this.player.x,y:this.player.y,vx:Math.cos(a)*900,vy:Math.sin(a)*900,radius:22,damage:420*this.player.damageMultiplier,life:2.2,pierce:30,bounce:0,color:"#ffd84d",knockback:180,explosionRadius:105,weapon:w,projectileStyle:"goldenBall"}));this.ultimateActive=false}else if(id==="unbreakable"){this.ultimateBuff={id:"unbreakable",time:7,pulse:0};this.ultimateBuffTimer=7}else if(id==="all_out_attack"){this.allyBuffTimer=8;this.allyBuffStrength=.80;this.ultimateBuff={id:"captain",time:8};this.ultimateBuffTimer=8}else if(id==="overclock_network"){for(const w of this.player.weapons)if(w.def.tags?.some(x=>["deployable","defensive","summon"].includes(x)))w.cool=0;for(const q of this.turrets)q.cool=0;for(const m of this.mines)m.arm=0;this.ultimateBuff={id:"technician",time:8};this.ultimateBuffTimer=8}else if(id==="breakaway"){this.ultimateBuff={id:"breakaway",time:6,trail:0};this.ultimateBuffTimer=6}else{const r=Math.random();if(r<.25){this.player.goldenBoostTimer=15}else if(r<.5){this.player.tempFrenzy=12}else if(r<.75){this.player.pickupShield+=3;this.player.heal(this.player.maxHp*.35)}else{this.player.gainXP(90);this.rerollsRemaining=Math.min(this.rerollsMax,this.rerollsRemaining+1)}this.ultimateActive=false}};

// ---------- Modal queue, mutations, boss rewards ----------
Game.prototype.queueMeta=function(type,data,priority){this.rewardQueue||=[];this.rewardQueue.push({type,data,priority});this.rewardQueue.sort((a,b)=>a.priority-b.priority)};
Game.prototype.processMeta=function(){if(this.metaBusy||this.state!=="PLAYING"||!this.rewardQueue?.length)return;const r=this.rewardQueue.shift();this.metaBusy=true;this.state="META_MODAL";this.input.clear();const title=document.getElementById("vsxMetaTitle"),box=document.getElementById("vsxMetaChoices");document.getElementById("vsxMetaModal").classList.add("active");box.innerHTML="";let choices=[];if(r.type==="mutation"){title.textContent=t("mutation");const defs=vsxEnsureWeaponMutations(r.data?.weapon?.id);choices=defs.map(m=>({name:m.name[VSX.lang],desc:m.desc[VSX.lang],act:()=>{r.data.weapon.mutationId=m.id;vsxDiscover("mutations",m.id);this.texts.push(new FloatingText(this.player.x,this.player.y-55,m.name[VSX.lang],"#ca72ff",18))}}));if(!choices.length){document.getElementById("vsxMetaModal").classList.remove("active");this.metaBusy=false;this.state="PLAYING";this.input.clear();queueMicrotask(()=>this.processMeta());return}}else if(r.type==="boss"){title.textContent=t("bossTreasure");choices=this.buildBossRewards()}else if(r.type==="shrine"){title.textContent=t("shrine");choices=this.buildShrineChoices(r.data.object)}for(const [i,c] of choices.entries()){const e=document.createElement("div");e.className="vsxMetaCard";e.innerHTML=`<div class="key">${i+1}</div><h3>${VSX.esc(c.name)}</h3><p>${VSX.esc(c.desc||"")}</p>`;e.onclick=()=>{c.act();this.closeMeta()};box.appendChild(e)}this.metaChoices=choices};
Game.prototype.closeMeta=function(){document.getElementById("vsxMetaModal").classList.remove("active");this.metaBusy=false;this.state="PLAYING";this.input.clear();setTimeout(()=>{if(this.rewardQueue?.length)this.processMeta();else if(this.pendingLevels>0)VSX_BASE_OPEN_LEVEL.call(this)},0)};
Game.prototype.buildBossRewards=function(){const a=[];if(this.player.weaponSlots<MAX_WEAPON_SLOTS)a.push({name:t("weaponSlot"),desc:VSX.lang==="vi"?"Mở thêm 1 ô vũ khí cho trận này.":"Expand weapon capacity by one for this run.",act:()=>{this.player.weaponSlots=Math.min(MAX_WEAPON_SLOTS,this.player.weaponSlots+1)}});if(this.player.passiveSlots<MAX_PASSIVE_SLOTS)a.push({name:t("passiveSlot"),desc:VSX.lang==="vi"?"Mở thêm 1 ô nội tại cho trận này.":"Expand passive capacity by one for this run.",act:()=>{this.player.passiveSlots=Math.min(MAX_PASSIVE_SLOTS,this.player.passiveSlots+1)}});if(this.rerollsRemaining<this.rerollsMax)a.push({name:"+1 Reroll",desc:VSX.lang==="vi"?"Hoàn lại một lượt Đổi Lại Lựa Chọn.":"Restore one level-up reroll.",act:()=>this.rerollsRemaining++});a.push({name:VSX.lang==="vi"?"Hồi Đầy Máu":"Full Heal",desc:VSX.lang==="vi"?"Hồi đầy HP và một phần barrier.":"Restore all HP and some barrier.",act:()=>{this.player.heal(99999);this.player.barrierHp=this.player.barrierMax}});a.push({name:VSX.lang==="vi"?"Bùng Nổ XP":"XP Surge",desc:"+25% XP gain for the rest of the run.",act:()=>{this.shrineMods.xp*=1.25}});const ws=this.player.weapons.filter(w=>w.level<5);if(ws.length)a.push({name:VSX.lang==="vi"?"Song Nâng Cấp Vũ Khí":"Double Weapon Upgrade",desc:VSX.lang==="vi"?"Tăng ngẫu nhiên một vũ khí tối đa 2 cấp.":"Upgrade a random weapon by up to two levels.",act:()=>{const w=pick(ws);w.level=Math.min(5,w.level+2);this.scanMutations()}});const epics=Object.keys(PASSIVE_DEFINITIONS).filter(id=>PASSIVE_DEFINITIONS[id].rarity==="epic"&&this.player.passiveLevel(id)<PASSIVE_DEFINITIONS[id].maxLevel&&(this.player.passiveLevel(id)>0||this.player.passives.size<this.player.passiveSlots));if(epics.length)a.push({name:VSX.lang==="vi"?"Nội Tại Epic":"Epic Passive",desc:VSX.lang==="vi"?"Nhận hoặc nâng một Nội Tại Epic ngẫu nhiên.":"Gain or upgrade a random Epic passive.",act:()=>this.player.addPassive(pick(epics))});while(a.length>3)a.splice((Math.random()*a.length)|0,1);return a.slice(0,3)};
Game.prototype.buildShrineChoices=function(obj){const choices=[];for(const [id,d] of Object.entries(SHRINE_DEFINITIONS)){choices.push({name:d.name[VSX.lang],desc:`${d.gain[VSX.lang]} • ${d.cost[VSX.lang]}`,act:()=>{this.stats.shrines++;if(id==="power"){this.shrineMods.damage*=1.25;this.shrineMods.enemyHp*=1.18}else if(id==="greed"){this.shrineMods.xp*=1.30;this.shrineMods.elite*=1.7}else if(id==="sacrifice"){this.player.hp=Math.max(1,this.player.hp*.70);const pool=Object.keys(PASSIVE_DEFINITIONS).filter(x=>PASSIVE_DEFINITIONS[x].rarity==="epic"&&this.player.passiveLevel(x)<PASSIVE_DEFINITIONS[x].maxLevel&&(this.player.passiveLevel(x)>0||this.player.passives.size<this.player.passiveSlots));if(pool.length)this.player.addPassive(pick(pool))}else{const eligible=this.player.weapons.filter(w=>!w.evolutionId&&!w.def.rewardOnly&&!['golden_ball_cannon','virgil_vandijk'].includes(w.id));if(eligible.length){const old=pick(eligible),ids=Object.keys(WEAPON_DEFINITIONS).filter(x=>!WEAPON_DEFINITIONS[x].rewardOnly&&!this.player.weapons.some(w=>w.id===x));if(ids.length){const nw=new WeaponInstance(pick(ids));nw.level=old.level;this.player.weapons[this.player.weapons.indexOf(old)]=nw;vsxDiscover("weapons",nw.id)}}}obj.used=true}})}return choices.slice(0,3)};
Game.prototype.scanMutations=function(){for(const w of this.player.weapons){if(w.level<5||w.mutationId||(w.def.rewardOnly&&!w.def.marvelSignatureMutation)||this.mutationQueued.has(w))continue;const defs=vsxEnsureWeaponMutations(w.id);this.mutationQueued.add(w);if(defs.length)this.queueMeta("mutation",{weapon:w},2)}};
const VSX_BASE_OPEN_LEVEL=Game.prototype.openLevelUp;
Game.prototype.openLevelUp=function(){if(this.rewardQueue?.some(r=>r.priority<=3)||this.metaBusy){return}return VSX_BASE_OPEN_LEVEL.call(this)};
const VSX_BASE_CHOOSE=Game.prototype.chooseUpgrade;
Game.prototype.chooseUpgrade=function(i){const before=this.player?.weapons.map(w=>[w,w.level]);const r=VSX_BASE_CHOOSE.call(this,i);this.scanMutations();return r};
const VSX_BASE_CHEST=Game.prototype.openChest;
Game.prototype.openChest=function(){const r=VSX_BASE_CHEST.call(this);this.scanMutations();return r};
const VSX_BASE_CLOSE_CHEST=Game.prototype.closeChest;
Game.prototype.closeChest=function(){const r=VSX_BASE_CLOSE_CHEST.call(this);this.scanMutations();setTimeout(()=>{if(this.state==="PLAYING"){if(this.rewardQueue?.length)this.processMeta();else if(this.pendingLevels>0)this.openLevelUp()}},0);return r};

// ---------- Mini-bosses / telegraphs ----------
class VSX_Telegraph{
 constructor(o){Object.assign(this,{type:"circle",x:0,y:0,x2:0,y2:0,r:60,life:1,maxLife:o.life||1,color:"#ff4058",callback:null,dead:false},o);this.maxLife=this.life}
 update(dt){this.life-=dt;if(this.life<=0){if(this.callback)this.callback(this);this.dead=true}}
 render(g){const a=.25+.45*(1-this.life/this.maxLife);g.save();g.globalAlpha=a;g.strokeStyle=this.color;g.fillStyle="rgba(255,40,70,.09)";g.lineWidth=(3+3*(1-this.life/this.maxLife))*(window.VSX_SETTINGS_V5?.telegraphScale?.()||1);if(this.type==="line"){g.beginPath();g.moveTo(this.x,this.y);g.lineTo(this.x2,this.y2);g.stroke()}else if(this.type==="cone"){g.beginPath();g.moveTo(this.x,this.y);const ang=Math.atan2(this.y2-this.y,this.x2-this.x);g.arc(this.x,this.y,this.r,ang-.42,ang+.42);g.closePath();g.fill();g.stroke()}else{g.beginPath();g.arc(this.x,this.y,this.r,0,Math.PI*2);g.fill();g.stroke()}g.restore()}
}
class VSX_MiniBoss extends Enemy{
 constructor(kind,x,y){super("tank",x,y,1,null);const d=MINIBOSS_DEFINITIONS[kind];this.kind=kind;this.isMiniBoss=true;this.size=30;this.maxHp=d.hp*(1+game.time/500);this.hp=this.maxHp;this.damage=d.damage;this.speed=d.speed;this.xp=55;this.def={...this.def,color:d.color,shape:"hex"};this.timer=2;this.attackState=null;vsxApplyDifficulty(this)}
 update(dt){this.flash=Math.max(0,this.flash-dt);const sm=this.updateStatus(dt);const p=game.player,dx=p.x-this.x,dy=p.y-this.y,d=Math.hypot(dx,dy)||1,nx=dx/d,ny=dy/d;this.timer-=dt;if(this.kind==="sniper"){if(d<360){this.x-=nx*this.speed*dt;this.y-=ny*this.speed*dt}else if(d>520){this.x+=nx*this.speed*dt;this.y+=ny*this.speed*dt}if(this.timer<=0){this.timer=3.1;const tx=p.x,ty=p.y;game.telegraphs.push(new VSX_Telegraph({type:"line",x:this.x,y:this.y,x2:tx,y2:ty,life:.9,callback:()=>{const n=normalize(tx-this.x,ty-this.y);game.enemyProjectiles.push(new Projectile({x:this.x,y:this.y,vx:n.x*520,vy:n.y*520,radius:7,damage:this.damage,life:2.5,color:"#ff69df",owner:"enemy",critAllowed:false}))}}))}}else if(this.kind==="juggernaut"||this.kind==="assassin"){this.x+=nx*this.speed*sm*dt;this.y+=ny*this.speed*sm*dt;if(this.timer<=0){this.timer=this.kind==="assassin"?2.0:3.0;const tx=p.x,ty=p.y;game.telegraphs.push(new VSX_Telegraph({type:"line",x:this.x,y:this.y,x2:tx,y2:ty,life:.65,callback:()=>{const n=normalize(tx-this.x,ty-this.y),sp=this.kind==="assassin"?620:480;this.x+=n.x*120;this.y+=n.y*120;game.enemyWaves.push({wave:new WaveEffect(this.x,this.y,this.kind==="assassin"?90:135,.55,this.damage*.6,0,null,"#ff627e")})}}))}}else{this.x+=nx*this.speed*sm*dt;this.y+=ny*this.speed*sm*dt;if(this.timer<=0){this.timer=this.kind==="summoner"?4:this.kind==="necromancer"?5:3.5;if(this.kind==="summoner"){for(let i=0;i<4;i++)game.enemies.push(vsxApplyDifficulty(new Enemy(pick(["grunt","runner","swarmer"]),this.x+rand(80,-80),this.y+rand(80,-80),game.difficulty)))}else if(this.kind==="necromancer"){const types=game.recentDeaths.slice(-4).map(x=>x.type).filter(x=>ENEMY_DEFINITIONS[x]&&!ENEMY_DEFINITIONS[x].special);for(const type of (types.length?types:["grunt","runner"]))game.enemies.push(vsxApplyDifficulty(new Enemy(type,this.x+rand(100,-100),this.y+rand(100,-100),game.difficulty*.9)))}else{for(const e of game.grid.queryCircle(this.x,this.y,220))if(e!==this&&!e.dead)e.shieldActive=true}}}if(d<this.size+p.radius)p.takeDamage(this.damage,{enemy:this,physical:true})}
 die(drop=true){if(this.dead)return;super.die(false);game.stats.minibosses++;game.addUltimateCharge(24);game.miniBoss=null;game.lastMajorEncounterTime=game.time;const r=Math.random();if(r<.28)game.chests.push(new Chest(this.x,this.y));else if(r<.56)game.pickups.push(new Pickup(this.x,this.y,"medkit"));else if(r<.78){game.player.gainXP(75)}else game.rerollsRemaining=Math.min(game.rerollsMax,game.rerollsRemaining+1);VSX.announce(t("miniboss"),MINIBOSS_DEFINITIONS[this.kind].name[VSX.lang],"#ff839a")}
}

// ---------- World objects ----------
class VSX_WorldObject{
 constructor(type,x,y){this.type=type;this.x=x;this.y=y;this.r=type==="shrine"?24:18;this.hp=type==="barrel"?55:type==="crate"?65:type==="generator"?80:99999;this.maxHp=this.hp;this.dead=false;this.used=false;this.life=type==="fountain"?150:120;this.vsxPulseCd=0;this.vsxPulseMax=18}
 update(dt){this.life-=dt;if(this.life<=0&&this.type!=="shrine")this.dead=true;if(["barrel","crate","generator"].includes(this.type)){for(const p of game.projectiles){if(p.dead)continue;if(Math.hypot(p.x-this.x,p.y-this.y)<this.r+p.radius){this.hp-=Math.max(1,p.damage);if(p.pierce<=0)p.dead=true;if(this.hp<=0){this.destroy();break}}}}if(this.type==="fountain"){this.vsxPulseCd=Math.max(0,(this.vsxPulseCd||0)-dt);const p=game.player,d=Math.hypot(p.x-this.x,p.y-this.y);if(d<72){p.heal(p.maxHp*.018*dt,false);if(Math.random()<dt*2.2)game.spark(this.x+rand(44,-44),this.y+rand(44,-44),"#8ef5ff",1)}}}
 destroy(){if(this.dead)return;this.dead=true;if(this.type==="barrel"){game.explosion(this.x,this.y,120,65,"#ff8c42",110,{id:"explosive_barrel",def:{tags:["environment","explosive"]}},false);for(const o of game.worldObjects)if(!o.dead&&o.type==="barrel"&&Math.hypot(o.x-this.x,o.y-this.y)<150)o.destroy()}else if(this.type==="crate"){game.pickups.push(new Pickup(this.x,this.y,Math.random()<.35?"medkit":Math.random()<.5?"xp":"frenzy"))}else if(this.type==="generator"){const targets=game.nearestList(this.x,this.y,360,6);for(const e of targets)game.damageEnemy(e,42,{source:{id:"generator",def:{tags:["environment","electric"]}},canCrit:false,damageType:"electric"});game.spark(this.x,this.y,"#7deaff",22)}}
 interact(){if(this.type==="fountain"){const p=game.player;if(!p)return;if((this.vsxPulseCd||0)>0){game.texts.push(new FloatingText(this.x,this.y-74,`${VSX.lang==="vi"?"ĐANG SẠC":"RECHARGING"} ${Math.ceil(this.vsxPulseCd)}s`,"#83ddeb",11));return}this.vsxPulseCd=this.vsxPulseMax||18;const hpBefore=p.hp;p.heal(p.maxHp*.16,true);if((p.pickupShield||0)<2)p.pickupShield=(p.pickupShield||0)+1;let cleared=0;for(const q of game.enemyProjectiles||[]){if(q.dead)continue;if(Math.hypot(q.x-this.x,q.y-this.y)<=175){q.dead=true;cleared++;if(game.stats){game.stats.projectilesBlocked=(game.stats.projectilesBlocked||0)+1;game.stats.damagePrevented=(game.stats.damagePrevented||0)+(q.damage||8)}}}game.explosion(this.x,this.y,150,18,"#7feeff",115,{id:"healing_fountain_pulse",def:{tags:["environment","support","area"]}},false);game.spark(this.x,this.y,"#b8fbff",30);game.shake(4,.12);VSX.announce(VSX.lang==="vi"?"TRẠM HỒI PHỤC":"HEALING FOUNTAIN",VSX.lang==="vi"?`XUNG THÁNH ĐỊA • HỒI ${Math.round(p.hp-hpBefore)} HP • XÓA ${cleared} ĐẠN`:`SANCTUARY PULSE • +${Math.round(p.hp-hpBefore)} HP • ${cleared} SHOTS CLEARED`,"#8ef5ff");try{vsxDiscover("world_objects","fountain")}catch(_){}return}if(this.used)return;if(this.type==="shrine"){game.queueMeta("shrine",{object:this},3);game.processMeta()}else if(this.type==="goal"){this.used=true;game.score+=500;const w=game.player.weapons.find(w=>w.def.tags?.includes("football")||["football","golden_ball_cannon","bicycle_kick","corner_kick"].includes(w.id));if(w)w.cool=0;game.player.goldenBoostTimer=Math.max(game.player.goldenBoostTimer,8);VSX.announce(VSX.lang==="vi"?"VÀOOOO!":"GOAL!",VSX.lang==="vi"?"+500 ĐIỂM • BÓNG ĐÁ ĐƯỢC BUFF":"+500 SCORE • FOOTBALL BOOST","#ffd84d")}}
 render(g){g.save();g.translate(this.x,this.y);const pd=game?.player?Math.hypot(game.player.x-this.x,game.player.y-this.y):9999;if(this.type==="barrel"){g.fillStyle="#b74b34";g.fillRect(-13,-18,26,36);g.strokeStyle="#ffb15a";g.strokeRect(-13,-18,26,36);}else if(this.type==="crate"){g.fillStyle="#8f6b42";g.fillRect(-18,-18,36,36);g.strokeStyle="#d4ad75";g.strokeRect(-18,-18,36,36);g.beginPath();g.moveTo(-18,-18);g.lineTo(18,18);g.moveTo(18,-18);g.lineTo(-18,18);g.stroke()}else if(this.type==="fountain"){const pulse=.5+.5*Math.sin((game?.time||0)*3.2),ready=(this.vsxPulseCd||0)<=0,cd=Math.max(0,this.vsxPulseCd||0),ratio=ready?1:1-cd/(this.vsxPulseMax||18);g.globalAlpha=.15+.07*pulse;g.fillStyle=ready?"#62e8f4":"#4a9ead";g.beginPath();g.arc(0,0,72,0,Math.PI*2);g.fill();g.globalAlpha=.56;g.strokeStyle=ready?"#8ff7ff":"#5aa9b8";g.lineWidth=2;g.beginPath();g.arc(0,0,72,0,Math.PI*2);g.stroke();g.globalAlpha=1;g.strokeStyle=ready?"#d7ffff":"#70c7d4";g.lineWidth=3;g.beginPath();g.arc(0,0,78,-Math.PI/2,-Math.PI/2+Math.PI*2*clamp(ratio,0,1));g.stroke();g.shadowBlur=ready?14:5;g.shadowColor="#8ef5ff";g.fillStyle="#70cfdb";g.fillRect(-15,-11,30,22);g.fillStyle="#e0ffff";g.fillRect(-3,-8,6,16);g.fillRect(-8,-3,16,6);g.shadowBlur=0;}else if(this.type==="generator"){g.fillStyle="#526a7d";g.fillRect(-16,-20,32,40);g.fillStyle="#7ff4ff";g.fillRect(-5,-13,10,18);}else if(this.type==="goal"){g.strokeStyle="#fff";g.lineWidth=4;g.strokeRect(-35,-25,70,50);g.globalAlpha=.3;for(let x=-30;x<=30;x+=10){g.beginPath();g.moveTo(x,-25);g.lineTo(x,25);g.stroke()}g.globalAlpha=1}else{g.shadowBlur=18;g.shadowColor="#ad7cff";g.fillStyle="#7d60a8";g.beginPath();g.moveTo(0,-28);g.lineTo(22,18);g.lineTo(-22,18);g.closePath();g.fill();g.fillStyle="#d7b6ff";g.fillRect(-4,-9,8,18)}g.restore()}
}
class VSX_HealingZone{constructor(x,y){this.x=x;this.y=y;this.r=75;this.life=6;this.dead=false}update(dt){this.life-=dt;if(Math.hypot(game.player.x-this.x,game.player.y-this.y)<this.r)game.player.heal(game.player.maxHp*.025*dt,false);if(this.life<=0)this.dead=true}render(g){g.save();g.globalAlpha=.18;g.fillStyle="#6dffa2";g.beginPath();g.arc(this.x,this.y,this.r,0,Math.PI*2);g.fill();g.strokeStyle="#a2ffc2";g.stroke();g.restore()}}
class VSX_TreasureRunner extends Enemy{constructor(x,y){super("runner",x,y,1,null);this.isTreasureRunner=true;this.maxHp=220;this.hp=220;this.speed=190;this.damage=0;this.xp=70;this.def={...this.def,color:"#ffd84d",shape:"circle"};this.escape=26}update(dt){this.escape-=dt;const n=normalize(this.x-game.player.x,this.y-game.player.y);this.x+=n.x*this.speed*dt;this.y+=n.y*this.speed*dt;if(this.escape<=0)this.dead=true}die(){if(this.dead)return;super.die(false);game.chests.push(new Chest(this.x,this.y));game.pickups.push(new Pickup(this.x+20,this.y,"golden_boost"));game.player.gainXP(80)}}

Game.prototype.spawnMiniBoss=function(){if(this.miniBoss||this.boss||this.worldEvent||this.time-this.lastMajorEncounterTime<15)return;const kind=pick(Object.keys(MINIBOSS_DEFINITIONS)),a=Math.random()*Math.PI*2,rr=Math.hypot(innerWidth,innerHeight)*.55+150;const e=new VSX_MiniBoss(kind,this.player.x+Math.cos(a)*rr,this.player.y+Math.sin(a)*rr);this.miniBoss=e;this.enemies.push(e);this.lastMajorEncounterTime=this.time;vsxDiscover("enemies","mini_"+kind);VSX.announce(t("miniboss"),MINIBOSS_DEFINITIONS[kind].name[VSX.lang],"#ff7892")};
Game.prototype.spawnFormation=function(){if(this.enemies.length>GAME_CONFIG.maxEnemies-18||this.boss||this.miniBoss)return;const patterns=["circle","arrow","wall","pincer","convoy"],pat=pick(patterns),types=["grunt","runner","swarmer","shooter"],baseA=Math.random()*Math.PI*2,baseR=480;const pts=[];if(pat==="circle")for(let i=0;i<12;i++)pts.push([Math.cos(i*Math.PI/6)*baseR,Math.sin(i*Math.PI/6)*baseR]);else if(pat==="wall")for(let i=-5;i<=5;i++)pts.push([Math.cos(baseA)*baseR-Math.sin(baseA)*i*45,Math.sin(baseA)*baseR+Math.cos(baseA)*i*45]);else if(pat==="pincer")for(let side of [-1,1])for(let i=-2;i<=2;i++)pts.push([Math.cos(baseA+side*Math.PI/2)*baseR+i*35,Math.sin(baseA+side*Math.PI/2)*baseR]);else if(pat==="arrow")for(let i=0;i<10;i++){const row=Math.floor(i/2),side=i%2?1:-1;pts.push([Math.cos(baseA)*(baseR-row*35)-Math.sin(baseA)*side*row*40,Math.sin(baseA)*(baseR-row*35)+Math.cos(baseA)*side*row*40])}else for(let i=0;i<9;i++){const a=baseA+i*Math.PI*2/9;pts.push([Math.cos(a)*(baseR+(i%2)*45),Math.sin(a)*(baseR+(i%2)*45)])}for(const [dx,dy] of pts)this.enemies.push(vsxApplyDifficulty(new Enemy(pick(types),this.player.x+dx,this.player.y+dy,this.difficulty)))};
Game.prototype.spawnWorldObject=function(){const a=Math.random()*Math.PI*2,rr=rand(650,250),x=this.player.x+Math.cos(a)*rr,y=this.player.y+Math.sin(a)*rr;let type=Math.random()<.10?"shrine":pick(["barrel","crate","fountain","generator","goal"]);if(type==="shrine"&&this.worldObjects.some(o=>!o.dead&&o.type==="shrine"))type="crate";this.worldObjects.push(new VSX_WorldObject(type,x,y));try{vsxDiscover("world_objects",type)}catch(_){}};
Game.prototype.startWorldEvent=function(){if(this.worldEvent||this.boss||this.miniBoss||this.time-this.lastMajorEncounterTime<15)return;const id=pick(Object.keys(WORLD_EVENT_DEFINITIONS)),d=WORLD_EVENT_DEFINITIONS[id];this.worldEvent={id,time:d.duration,max:d.duration};this.lastMajorEncounterTime=this.time;this.eventTick=0;VSX.announce(t("worldEvent"),d.name[VSX.lang],"#ffb05d");if(id==="treasure_runner"){const a=Math.random()*Math.PI*2,rr=420;this.enemies.push(new VSX_TreasureRunner(this.player.x+Math.cos(a)*rr,this.player.y+Math.sin(a)*rr))}};

// ---------- Synergies ----------
Game.prototype.checkSynergies=function(){for(const [id,d] of Object.entries(SYNERGY_DEFINITIONS)){const yes=!!d.req(this);if(yes&&!this.activeSynergies.has(id)){this.activeSynergies.add(id);this.stats.synergies.add(id);vsxDiscover("synergies",id);VSX.announce(t("synergy"),d.name[VSX.lang],"#8fe3b5")}else if(!yes&&this.activeSynergies.has(id))this.activeSynergies.delete(id)}};

// ---------- Enemy kill hooks / achievements / ultimate ----------
const VSX_BASE_DIE=Enemy.prototype.die;
Enemy.prototype.die=function(drop=true){if(this.dead)return;const score0=game.score;const wasElite=!!this.elite,type=this.type,special=this.specialId,isBoss=this.isBoss;VSX_BASE_DIE.call(this,drop);const d=DIFFICULTY_DEFINITIONS[game.difficultyMode||"normal"];game.score=score0+(game.score-score0)*d.score;if(game.stats){if(wasElite)game.stats.elites++;game.killStreak.count++;game.killStreak.timer=3;const charge=this.isMiniBoss?24:isBoss?35:wasElite?6:Math.max(.25,1.25-(game.ultKillHeat||0)*.08);game.addUltimateCharge(charge);game.ultKillHeat=Math.min(10,(game.ultKillHeat||0)+1);game.recentDeaths.push({type,x:this.x,y:this.y,source:game._lastKillSource||'',bloodbound:this.vsxBloodbound||null,enemyId:this.id});if(game.recentDeaths.length>20)game.recentDeaths.shift();if(this.golden){game.gems.push(new XPGem(this.x+12,this.y,12));if(Math.random()<.18)game.pickups.push(new Pickup(this.x-12,this.y,"golden_boost"))}const source=game._lastKillSource||"";if(["football","golden_ball_cannon","bicycle_kick","corner_kick"].includes(source)){game.killStreak.footballKills++;game.killStreak.footballTimer=1.8;if(game.killStreak.footballKills>=3)vsxAchievement("hat_trick")}}
 if(game.specialKilled?.ronaldo&&game.specialKilled?.messi)vsxAchievement("goat_debate");if(game.mbappeRescued)vsxAchievement("prison_break");if(game.time>=600&&game.player.weapons.length<=3)vsxAchievement("minimalist");if(game.activeSynergies?.has("one_man_army")&&game.kills>=500)vsxAchievement("one_man_army");};
// capture kill source reliably from damage pipeline
const VSX_DAMAGE_WITH_SOURCE=Game.prototype.damageEnemy;
Game.prototype.damageEnemy=function(e,a,o={}){const old=this._lastKillSource;this._lastKillSource=o.source?.id||this._damageAttribution||o.damageType||"";try{return VSX_DAMAGE_WITH_SOURCE.call(this,e,a,o)}finally{this._lastKillSource=old}};

const VSX_BASE_BOSS_DIE=Boss.prototype.die;
Boss.prototype.die=function(drop=true){if(this.dead)return;const low=game.player.hp/game.player.maxHp<.2&&game.player.passiveLevel("glass_cannon")>0;VSX_BASE_BOSS_DIE.call(this,drop);game.stats.bosses++;game.queueMeta("boss",{},1);if(low)vsxAchievement("glass_jaw")};

// ---------- Boss phases ----------
const VSX_BASE_BOSS_UPDATE=Boss.prototype.update;
Boss.prototype.update=function(dt){VSX_BASE_BOSS_UPDATE.call(this,dt);if(this.dead)return;const ratio=this.hp/this.maxHp,next=ratio<=.4?3:ratio<=.7?2:1;if(next>(this.vsxPhase||1)){this.vsxPhase=next;VSX.announce(VSX.lang==="vi"?`BOSS GIAI ĐOẠN ${next}`:`BOSS PHASE ${next}`,VSX.lang==="vi"?"TITAN ĐỎ THẪM NỔI GIẬN":"CRIMSON TITAN ESCALATES","#ff4768");game.shake(13,.35);this.vsxAbilityTimer=1}this.vsxAbilityTimer=(this.vsxAbilityTimer||4)-dt;if(this.vsxPhase>=2&&this.vsxAbilityTimer<=0){this.vsxAbilityTimer=this.vsxPhase===3?3.2:4.8;const p=game.player;if(this.vsxPhase===2){for(let i=0;i<3;i++){const x=p.x+rand(160,-160),y=p.y+rand(160,-160);game.telegraphs.push(new VSX_Telegraph({x,y,r:58,life:.9,callback:()=>{game.explosion(x,y,62,this.damage*.85,"#ff5a3c",80,{id:"crimson_meteor",def:{tags:["boss"]}},false);if(Math.hypot(p.x-x,p.y-y)<62+p.radius)p.takeDamage(this.damage*.7,{boss:true})}}))}}else{for(let i=0;i<20;i++){const a=i*Math.PI/10;game.enemyProjectiles.push(new Projectile({x:this.x,y:this.y,vx:Math.cos(a)*280,vy:Math.sin(a)*280,radius:6,damage:this.damage*.65,life:3.2,color:"#ff355f",owner:"enemy",critAllowed:false}))}if(game.difficultyMode==="nightmare")for(let i=0;i<5;i++)game.enemies.push(vsxApplyDifficulty(new Enemy("runner",this.x+rand(100,-100),this.y+rand(100,-100),game.difficulty)))}}};

// Red Card cannot execute mini-boss/boss
ATTACK_BEHAVIORS.redCard=function(w,s){const pool=game.grid.queryCircle(game.player.x,game.player.y,s.range).filter(e=>!e.dead&&!e.isCaptive);if(!pool.length)return;pool.sort((a,b)=>b.hp-a.hp);const e=pool[0];if(!e.isBoss&&!e.isMiniBoss&&!e.elite&&e.hp/e.maxHp<(.25+(w.special==="doubleRed"?.08:0))){game.texts.push(new FloatingText(e.x,e.y-e.size-18,"RED CARD — EXECUTED!","#ff3c4e",18));e.hp=0;e.die(true)}else{game.damageEnemy(e,s.damage*(e.isBoss||e.isMiniBoss?1.5:1),{source:w,canCrit:true,knockback:80,fromX:game.player.x,fromY:game.player.y});e.applyStatus("freeze",e.isBoss?.35:1.4,1,w);e.applyStatus("vulnerable",2,.18,w)}if(w.special==="doubleRed"&&Math.random()<.35){const e2=pool[1];if(e2)game.damageEnemy(e2,s.damage,{source:w,canCrit:false,knockback:55})}};

// ---------- Defensive attribution ----------
const VSX_BASE_WALL_UPDATE=BrickWall.prototype.update;
BrickWall.prototype.update=function(dt){const before=game.enemyProjectiles.filter(p=>!p.dead).length,hp=this.hp;VSX_BASE_WALL_UPDATE.call(this,dt);const after=game.enemyProjectiles.filter(p=>!p.dead).length;if(game.stats&&after<before){const n=before-after;game.stats.vvdBlocked+=n;game.stats.projectilesBlocked+=n;if(game.stats.vvdBlocked>=100)vsxAchievement("the_wall")}};
const VSX_BASE_GLOVE_UPDATE=GoalkeeperGloveEffect.prototype.update;
GoalkeeperGloveEffect.prototype.update=function(dt){const n=this.caught.length;VSX_BASE_GLOVE_UPDATE.call(this,dt);if(game.stats&&this.caught.length>n)game.stats.projectilesCaught+=this.caught.length-n;if(game.activeSynergies?.has("counterstrike")&&this.released){for(const p of game.projectiles.slice(-Math.min(12,this.caught.length)))if(p.weapon===this.weapon)p.damage*=1.25}};

// ---------- Level UI localization ----------
const VSX_BASE_GENERATE=Game.prototype.generateChoices;
Game.prototype.generateChoices=function(){const out=VSX_BASE_GENERATE.call(this);for(const c of out){if(c.type==="newWeapon"){c.name=weaponName(c.id);c.desc=weaponDesc(c.id);c.effect=t("newWeapon")}else if(c.type==="weaponLevel"){const w=this.player.weapons.find(w=>w.id===c.id);c.name=weaponName(c.id);c.desc=VSX.lang==="vi"?`Nâng ${weaponName(c.id)} lên cấp tiếp theo.`:`Upgrade ${weaponName(c.id)}.`}else if(c.type==="passive"){c.name=passiveName(c.id);c.desc=passiveDesc(c.id);c.effect=this.player.passiveLevel(c.id)?c.effect:t("newPassive")}else if(c.type==="evolution"){c.name=evolutionName(c.id);c.desc=VSX.lang==="vi"?`Tiến hóa ${weaponName(EVOLUTION_DEFINITIONS[c.id].weapon)}.`:`Evolve ${weaponName(EVOLUTION_DEFINITIONS[c.id].weapon)}.`;c.effect=t("weaponEvolution")}else if(c.type==="weaponSlot"){c.name=t("weaponSlot");c.desc=VSX.lang==="vi"?"Mở thêm một ô vũ khí trong trận này.":c.desc}else if(c.type==="passiveSlot"){c.name=t("passiveSlot");c.desc=VSX.lang==="vi"?"Mở thêm một ô nội tại trong trận này.":c.desc}else if(c.type==="heal"){c.name=VSX.lang==="vi"?"Sửa Chữa Khẩn Cấp":"Emergency Repair";c.desc=VSX.lang==="vi"?"Hồi 30% Máu Tối Đa.":c.desc;c.effect=t("heal")}}return out};
const VSX_BASE_RENDER_LEVEL=Game.prototype.renderLevelChoices;
Game.prototype.renderLevelChoices=function(){VSX_BASE_RENDER_LEVEL.call(this);document.querySelector("#levelModal h2").textContent=VSX.lang==="vi"?"LÊN CẤP — CHỌN 1":"LEVEL UP — CHOOSE 1";const cur=this.player.energySkipStacks*10;skipUpgradeBtn.innerHTML=`Q — ${t("skip")}<span class="boost">${VSX.lang==="vi"?`Tăng XP từ lượt bỏ: +${cur}% -> +${cur+10}%`:`Energy / XP gain: +${cur}% -> +${cur+10}% from skips`}</span>`;rerollUpgradeBtn.innerHTML=`E — ${t("reroll")} (${this.rerollsRemaining}/${this.rerollsMax})<span class="boost">${this.rerollsRemaining>0?(VSX.lang==="vi"?"Đổi mới cả 3 thẻ mà không tiêu cấp":"Refresh all 3 choices without spending this level"):(VSX.lang==="vi"?"Đã hết reroll":"No rerolls remaining this run")}</span>`};
const VSX_BASE_REROLL=Game.prototype.rerollLevelUp;
Game.prototype.rerollLevelUp=function(){const before=this.rerollsRemaining;const r=VSX_BASE_REROLL.call(this);if(this.stats&&this.rerollsRemaining<before)this.stats.rerolls++;return r};
const VSX_BASE_SKIP=Game.prototype.skipLevelUp;
Game.prototype.skipLevelUp=function(){if(this.stats)this.stats.skips++;return VSX_BASE_SKIP.call(this)};

// ---------- Game update / render / director ----------
const VSX_BASE_GAME_UPDATE=Game.prototype.update;
Game.prototype.update=function(dt){
 // pre-defense priority: gloves -> physical walls/bunkers -> player orbit defenses
 if(this.effects)for(const e of this.effects)if(e instanceof GoalkeeperGloveEffect&&!e.dead)e.update(0);
 if(this.defensiveWalls)for(const w of this.defensiveWalls)if(!w.dead)w.update(0);
 if(this.effects)for(const e of this.effects)if(e instanceof BunkerEffect&&!e.dead)e.update(0);
 VSX_BASE_GAME_UPDATE.call(this,dt);
 if(!this.player)return;
 // direction memory for dash
 let dx=0,dy=0;if(this.input.has("KeyW")||this.input.has("ArrowUp"))dy--;if(this.input.has("KeyS")||this.input.has("ArrowDown"))dy++;if(this.input.has("KeyA")||this.input.has("ArrowLeft"))dx--;if(this.input.has("KeyD")||this.input.has("ArrowRight"))dx++;if(dx||dy)this.lastMoveDir=normalize(dx,dy);
 this.dashCooldown=Math.max(0,this.dashCooldown-dt);if(this.dashTimer>0){this.dashTimer-=dt;this.player.x+=this.dashDir.x*900*dt;this.player.y+=this.dashDir.y*900*dt;this.player.invuln=Math.max(this.player.invuln,.08);if(Math.random()<dt*25)this.particles.push(new Particle(this.player.x,this.player.y,rand(20,-20),rand(20,-20),.35,"#66e8ff",5))}
 this.ultKillHeat=Math.max(0,(this.ultKillHeat||0)-dt*1.8);if(this.ultimateBuffTimer>0){this.ultimateBuffTimer-=dt;if(this.ultimateBuff){this.ultimateBuff.time=this.ultimateBuffTimer;if(this.ultimateBuff.id==="unbreakable"){this.ultimateBuff.pulse-=dt;if(this.ultimateBuff.pulse<=0){this.ultimateBuff.pulse=.8;this.effects.push(new WaveEffect(this.player.x,this.player.y,180,.55,24*this.player.damageMultiplier,110,{id:"ultimate_unbreakable",def:{tags:["ultimate"]}},"#87d9ff"))}}if(this.ultimateBuff.id==="breakaway"){this.ultimateBuff.trail-=dt;if(this.ultimateBuff.trail<=0){this.ultimateBuff.trail=.23;this.effects.push(new AreaEffect({x:this.player.x,y:this.player.y,radius:38,life:.7,damage:22*this.player.damageMultiplier,tick:.25,color:"rgba(90,220,255,.22)",weapon:{id:"ultimate_breakaway",def:{tags:["ultimate","area"]}}}))}}}}else if(this.ultimateActive){this.ultimateActive=false;this.ultimateBuff=null;this.player.recalc()}
 // manager timers
 this.killStreak.timer-=dt;if(this.killStreak.timer<=0){this.killStreak.count=0;document.getElementById("vsxStreak").textContent=""}this.killStreak.footballTimer-=dt;if(this.killStreak.footballTimer<=0)this.killStreak.footballKills=0;
 const thresholds={25:"RAMPAGE",50:"UNSTOPPABLE",100:"MASSACRE",250:"APOCALYPSE"};if(thresholds[this.killStreak.count]){document.getElementById("vsxStreak").textContent=thresholds[this.killStreak.count];setTimeout(()=>{if(document.getElementById("vsxStreak").textContent===thresholds[this.killStreak.count])document.getElementById("vsxStreak").textContent=""},1100)}
 this.checkSynergies();this.scanMutations();
 // encounter director
 this.miniBossCooldown-=dt;this.formationCooldown-=dt;this.worldObjectCooldown-=dt;this.eventCooldown-=dt;if(this.miniBossCooldown<=0){this.spawnMiniBoss();this.miniBossCooldown=95+Math.random()*30}if(this.formationCooldown<=0){this.spawnFormation();this.formationCooldown=28+Math.random()*18}if(this.worldObjectCooldown<=0){this.spawnWorldObject();this.worldObjectCooldown=18+Math.random()*14}if(this.eventCooldown<=0){this.startWorldEvent();this.eventCooldown=85+Math.random()*35}
 if(this.worldEvent){this.worldEvent.time-=dt;this.eventSpawnTimer-=dt;const id=this.worldEvent.id;if(id==="blood_moon"&&this.eventSpawnTimer<=0){this.eventSpawnTimer=.55;this.spawnManager.spawnOne()}if(id==="healing_rain"&&this.eventSpawnTimer<=0){this.eventSpawnTimer=3.2;this.healingZones.push(new VSX_HealingZone(this.player.x+rand(240,-240),this.player.y+rand(240,-240)))}if(id==="meteor_storm"&&this.eventSpawnTimer<=0){this.eventSpawnTimer=1.15;const x=this.player.x+rand(280,-280),y=this.player.y+rand(280,-280);this.telegraphs.push(new VSX_Telegraph({x,y,r:52,life:.8,callback:()=>{this.explosion(x,y,55,55,"#ff6c35",70,{id:"meteor_storm",def:{tags:["world_event","explosive"]}},false);if(Math.hypot(this.player.x-x,this.player.y-y)<60)this.player.takeDamage(28,{worldEvent:true})}}))}if(this.worldEvent.time<=0)this.worldEvent=null}
 for(const o of this.worldObjects)if(!o.dead)o.update(dt);for(const z of this.healingZones)if(!z.dead)z.update(dt);for(const q of this.telegraphs)if(!q.dead)q.update(dt);this.worldObjects=this.worldObjects.filter(o=>!o.dead&&Math.hypot(o.x-this.player.x,o.y-this.player.y)<2300).slice(-45);this.healingZones=this.healingZones.filter(z=>!z.dead);this.telegraphs=this.telegraphs.filter(q=>!q.dead).slice(-40);
 // encounter/codex/achievement checks
 for(const e of this.enemies)if(!e.dead)vsxDiscover("enemies",e.type||e.kind);if(this.mbappeRescued)vsxAchievement("prison_break");if(this.specialKilled?.ronaldo&&this.specialKilled?.messi)vsxAchievement("goat_debate");if(this.time>=300&&this.stats.hpDamageTaken<=0)vsxAchievement("clean_sheet");if(this.time>=600&&this.player.weapons.length<=3)vsxAchievement("minimalist");if(this.mbappeAlly&&!this.mbappeAlly.dead&&this.player.weapons.some(w=>w.id==="virgil_vandijk")&&this.player.weapons.some(w=>w.id==="golden_ball_cannon"))vsxAchievement("golden_generation");
 // interact hint
 const near=this.worldObjects.filter(o=>!o.dead&&((!o.used&&["shrine","goal"].includes(o.type))||o.type==="fountain")).sort((a,b)=>dist2(a,this.player)-dist2(b,this.player))[0],ih=document.getElementById("vsxInteractHint");if(near&&Math.hypot(near.x-this.player.x,near.y-this.player.y)<95){const fr=near.type==="fountain",ready=!fr||(near.vsxPulseCd||0)<=0;this.nearInteractable=ready?near:null;ih.style.display="block";ih.textContent=fr?(ready?(VSX.lang==="vi"?"E — XUNG THÁNH ĐỊA":"E — SANCTUARY PULSE"):(VSX.lang==="vi"?`TRẠM ĐANG SẠC ${Math.ceil(near.vsxPulseCd)}s`:`FOUNTAIN RECHARGING ${Math.ceil(near.vsxPulseCd)}s`)):t("interact")}else{this.nearInteractable=null;ih.style.display="none"}
 this.processMeta();this.player.recalc();
};

const VSX_BASE_ENEMY_UPDATE=Enemy.prototype.update;
Enemy.prototype.update=function(dt){if(game.worldEvent?.id==="overtime"&&!this.isBoss&&!this.isMiniBoss)dt*=1.18;return VSX_BASE_ENEMY_UPDATE.call(this,dt)};

const VSX_BASE_RENDER=Game.prototype.render;
Game.prototype.render=function(){VSX_BASE_RENDER.call(this);if(!this.player||this.state==="TITLE")return;ctx.save();ctx.translate(-this.camera.x,-this.camera.y);for(const o of this.worldObjects||[])if(!o.dead)o.render(ctx);for(const z of this.healingZones||[])if(!z.dead)z.render(ctx);ctx.restore();if(this.worldEvent?.id==="blackout"){ctx.save();const g=ctx.createRadialGradient(innerWidth/2,innerHeight/2,70,innerWidth/2,innerHeight/2,Math.max(innerWidth,innerHeight)*.52);g.addColorStop(0,"rgba(0,0,0,0)");g.addColorStop(.33,"rgba(0,0,0,.25)");g.addColorStop(1,"rgba(0,0,0,.88)");ctx.fillStyle=g;ctx.fillRect(0,0,innerWidth,innerHeight);ctx.restore()}ctx.save();ctx.translate(-this.camera.x,-this.camera.y);if(this.boss?.state==="chargeTelegraph"){const n=normalize(this.player.x-this.boss.x,this.player.y-this.boss.y);ctx.globalAlpha=.65;ctx.strokeStyle="#ff4058";ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(this.boss.x,this.boss.y);ctx.lineTo(this.boss.x+n.x*650,this.boss.y+n.y*650);ctx.stroke();ctx.globalAlpha=1}for(const q of this.telegraphs||[])if(!q.dead)q.render(ctx);ctx.restore()};

// ---------- Input ----------
game.input.gameKeys.add("ShiftLeft");game.input.gameKeys.add("ShiftRight");game.input.gameKeys.add("Space");game.input.gameKeys.add("KeyE");
const VSX_BASE_HANDLE=Game.prototype.handleKey;
Game.prototype.handleKey=function(code){if(this.state==="META_MODAL"&&/^Digit[123]$/.test(code)){const i=Number(code.slice(-1))-1;if(this.metaChoices?.[i]){this.metaChoices[i].act();this.closeMeta()}return}if(this.state==="SETUP")return;if(this.state==="PLAYING"){if(code==="ShiftLeft"||code==="ShiftRight"){this.tryDash();return}if(code==="Space"){this.useUltimate();return}if(code==="KeyE"){this.nearInteractable?.interact();return}}return VSX_BASE_HANDLE.call(this,code)};

// ---------- HUD / game over ----------
const VSX_BASE_HUD=Game.prototype.updateHUD;
Game.prototype.updateHUD=function(force=false){if(!force&&this.time!=null&&this.time<(this.hudClock||0))return;this.hudClock=(this.time||0)+.10;const p=this.player;if(!p)return;const hpPct=100*p.hp/p.maxHp;statsHud.innerHTML=`HP <b>${Math.ceil(p.hp)}/${p.maxHp}</b><div class="miniBar"><div class="miniFill" style="width:${hpPct}%"></div></div>${t("level")} <b>${p.level}</b><br>${t("kills")} <b>${this.kills}</b><br>${t("score")} <b>${Math.floor(this.score)}</b><br>${t("slots")} <b>W ${p.weapons.length}/${p.weaponSlots} • P ${p.passives.size}/${p.passiveSlots}</b>${p.barrierMax>0?`<br><span style='color:#8de8ff'>Barrier ${Math.ceil(p.barrierHp)}/${p.barrierMax}</span>`:""}${p.overhealShield>0?`<br><span style='color:#b2f5ff'>Overshield ${Math.ceil(p.overhealShield)}</span>`:""}<br><span style='color:#ffd86b'>${t("legends")}: CR7 ${this.specialKilled?.ronaldo?"OK":"·"} • M10 ${this.specialKilled?.messi?"OK":"·"}${this.trophyClaimed?" • CUP OK":""}</span><br><span style='color:#ffe08a'>MB9 ${this.mbappeRescued?(this.mbappeAlly&&!this.mbappeAlly.dead?"ALLY OK":"DOWN"):this.specialSpawned?.mbappe?"CELL":"·"}</span>`;timerHud.textContent=fmtTime(this.time);xpFill.style.width=`${100*p.xp/p.xpNeed}%`;xpText.textContent=`${t("energy")} ${Math.floor(p.xp)} / ${p.xpNeed} • ${t("gain")} x${p.xpGain.toFixed(2)}`;inventoryHud.innerHTML=`<b>${t("weapons")} ${p.weapons.length}/${p.weaponSlots}</b><br>${p.weapons.map(w=>`${w.name} Lv${w.level}${w.mutationId?" [M]":""}`).join("<br>")}<br><br><b>${t("passives")} ${p.passives.size}/${p.passiveSlots}</b><br>${[...p.passives].map(([id,l])=>`${passiveName(id)} Lv${l}`).join("<br>")||"—"}`;if(this.boss&&!this.boss.dead){bossWrap.style.display="block";bossName.textContent=VSX.lang==="vi"?`TITAN ĐỎ THẪM • GĐ ${this.boss.vsxPhase||1}`:`CRIMSON TITAN • PHASE ${this.boss.vsxPhase||1}`;bossFill.style.width=`${100*this.boss.hp/this.boss.maxHp}%`}else bossWrap.style.display="none";const dc=Math.max(0,this.dashCooldown||0),dp=100*(1-dc/4.5);document.getElementById("vsxDashLabel").textContent=t("dash");document.getElementById("vsxDashText").textContent=dc<=0?t("ready").replace(" — SPACE",""):dc.toFixed(1)+"s";document.getElementById("vsxDashFill").style.width=`${clamp(dp,0,100)}%`;document.getElementById("vsxUltLabel").textContent=t("ultimate");document.getElementById("vsxUltText").textContent=this.ultimateCharge>=100?t("ready"):Math.floor(this.ultimateCharge||0)+"%";document.getElementById("vsxUltFill").style.width=`${this.ultimateCharge||0}%`;const eh=document.getElementById("vsxEventHud");if(this.worldEvent){const d=WORLD_EVENT_DEFINITIONS[this.worldEvent.id];eh.style.display="block";eh.innerHTML=`<b>${d.name[VSX.lang]}</b><br><small>${d.desc[VSX.lang]} • ${this.worldEvent.time.toFixed(0)}s</small>`}else eh.style.display="none";const mh=document.getElementById("vsxMiniBossHud");if(this.miniBoss&&!this.miniBoss.dead){mh.style.display="block";mh.innerHTML=`<b>${t("miniboss")}: ${MINIBOSS_DEFINITIONS[this.miniBoss.kind].name[VSX.lang]}</b><div class="vsxBossMiniBar"><div class="vsxBossMiniFill" style="width:${100*this.miniBoss.hp/this.miniBoss.maxHp}%"></div></div>`}else mh.style.display="none"};

Game.prototype.renderDamageMeter=function(){const el=document.getElementById("vsxDamageMeter");if(!el||!this.stats)return;const total=this.stats.damageDealt||1,rows=Object.entries(this.stats.damageBy).sort((a,b)=>b[1]-a[1]).slice(0,8);el.innerHTML=`<b>${t("pauseStats")}</b><br>${rows.map(([id,v],i)=>`${i+1}. ${VSX.esc(WEAPON_DEFINITIONS[id]?weaponName(id):id==="MB9"?"MB9":id)} — ${Math.round(v)} (${(v/total*100).toFixed(1)}%)`).join("<br>")||"—"}`};
const VSX_BASE_TOGGLE=Game.prototype.togglePause;
Game.prototype.togglePause=function(){const r=VSX_BASE_TOGGLE.call(this);if(this.state==="PAUSED")this.renderDamageMeter();return r};
const VSX_BASE_END=Game.prototype.endGame;
Game.prototype.endGame=function(){if(this.state!=="PLAYING")return;this.state="GAME_OVER";this.input.clear();this.saveRecords();const s=this.stats,total=s.damageDealt||1,top=Object.entries(s.damageBy).sort((a,b)=>b[1]-a[1]).slice(0,5);document.getElementById("gameOverStats").innerHTML=`${t("survival")}: <b>${fmtTime(this.time)}</b><br>${t("score")}: <b>${Math.floor(this.score)}</b><br>${t("kills")}: <b>${this.kills}</b><br>${t("level")}: <b>${this.player.level}</b><br>${t("bosses")}: <b>${this.bossesDefeated}</b><br>${t("damageDealt")}: <b>${Math.round(s.damageDealt)}</b><br>${t("damageTaken")}: <b>${Math.round(s.damageTaken)}</b><br>${t("damagePrevented")}: <b>${Math.round(s.damagePrevented)}</b><br>${t("healing")}: <b>${Math.round(s.healing)}</b><br>${t("xpCollected")}: <b>${Math.round(s.xp)}</b><br>Rerolls: <b>${s.rerolls}</b> • Skips: <b>${s.skips}</b> • Dashes: <b>${s.dashes}</b> • Ultimates: <b>${s.ultimates}</b><br><br><b>${t("topDamage")}</b><br>${top.map(([id,v],i)=>`${i+1}. ${WEAPON_DEFINITIONS[id]?weaponName(id):id} — ${Math.round(v)} — ${(v/total*100).toFixed(1)}%`).join("<br>")||"—"}`;gameOverScreen.classList.add("active")};

// update boss/special discovery and language title state
vsxApplyLanguage();game.records=VSX.save.records.normal;game.renderRecords();
